import { CSPProvider } from "@/registry/erbium/ui/csp-provider";
import { OverlayProvider } from "@/registry/erbium/ui/overlay-provider";
import { Toaster } from "@/registry/erbium/ui/toast";
import type { ReactNode } from "react";

export function ShowcaseProviders({
  children,
  toast = false,
}: {
  children?: ReactNode;
  toast?: boolean;
}) {
  return (
    <CSPProvider disableStyleElements>
      <OverlayProvider>
        {children}
        {toast && <Toaster />}
      </OverlayProvider>
    </CSPProvider>
  );
}

export function ShowcaseSurface({ children }: { children?: ReactNode }) {
  return (
    <div
      data-slot="component-preview"
      className="relative isolate mx-auto flex min-h-64 w-full min-w-0 max-w-3xl items-center justify-center gap-section p-5 font-sans text-foreground contain-layout sm:p-8 [&>.min-w-72.max-w-2xl]:flex [&>.min-w-72.max-w-2xl]:flex-col [&>.min-w-72.max-w-2xl]:items-center [&>.min-w-72.max-w-2xl]:justify-center"
    >
      {children}
    </div>
  );
}

import { CopyButton } from "@/registry/erbium/blocks/copy-button";

export default function StatefulIconDemo() {
  return (
    <CopyButton
      value="Stateful icons animate between states."
      aria-label="Copy example text"
      variant="outline"
      timeout={1200}
    />
  );
}

import {
  Collapsible,
  CollapsibleContent,
  CollapsibleTrigger,
} from "@/registry/erbium/ui/collapsible";

import {
  ExpandableChevron as ExpandableChevronIcon,
  SidebarToggleIcon as SidebarToggleIconGraphic,
  ThemeToggleIcon as ThemeToggleIconGraphic,
} from "@/registry/erbium/ui/stateful-icon";

import { useState } from "react";

export function ExpandableChevronExample() {
  const [isOpen, setIsOpen] = useState(false);

  return (
    <Collapsible className="w-72" open={isOpen} onOpenChange={setIsOpen}>
      <CollapsibleTrigger className="flex w-full items-center rounded-lg border px-3 py-2 text-start">
        Project details
        <ExpandableChevronIcon className="ms-auto" isOpen={isOpen} />
      </CollapsibleTrigger>
      <CollapsibleContent className="px-3 py-2 text-caption text-muted-foreground">
        The two chevrons exchange positions as this section opens and closes.
      </CollapsibleContent>
    </Collapsible>
  );
}

export function SidebarToggleIconExample({ side }: { side: "left" | "right" }) {
  const [isOpen, setIsOpen] = useState(false);

  return (
    <button
      aria-expanded={isOpen}
      aria-label={`${isOpen ? "Close" : "Open"} ${side} sidebar`}
      className="flex items-center gap-related rounded-lg border px-3 py-2 text-caption"
      onClick={() => {
        setIsOpen((open) => !open);
      }}
      type="button"
    >
      <SidebarToggleIconGraphic isOpen={isOpen} side={side} />
      {side === "left" ? "Left" : "Right"} sidebar
    </button>
  );
}

export function ThemeToggleIconExample() {
  const [theme, setTheme] = useState<"light" | "dark">("light");

  return (
    <button
      aria-label={`Switch to ${theme === "light" ? "dark" : "light"} theme`}
      className="flex items-center gap-related rounded-lg border px-3 py-2 text-caption"
      onClick={() => {
        setTheme((current) => (current === "light" ? "dark" : "light"));
      }}
      type="button"
    >
      <ThemeToggleIconGraphic theme={theme} />
      {theme === "light" ? "Light" : "Dark"} theme
    </button>
  );
}

